@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{--bg:#101619;--panel:#161e21;--panel2:#1b2528;--line:#293638;--muted:#758487;--text:#e7eeea;--mint:#b9edc9;--lime:#d8f279;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);min-width:320px}button{font:inherit;color:inherit;cursor:pointer}.app-shell{max-width:1600px;margin:auto;padding:0 48px}.topbar{height:74px;border-bottom:1px solid #263134;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:11px;align-items:center;text-decoration:none;color:var(--text)}.brand-mark{width:34px;height:34px;border:1px solid #536a60;border-radius:11px;display:grid;place-items:center;font:700 19px var(--display);color:var(--mint);position:relative}.brand-mark span{font-size:10px;color:var(--lime);position:absolute;right:4px;top:3px}.brand-name{font:700 12px var(--display);letter-spacing:1.55px}.brand-name span{color:#8f9c99;margin-left:4px;font-weight:500}.top-context,.top-actions{display:flex;align-items:center;gap:14px;color:#8f9c99;font:10px var(--mono);letter-spacing:.7px}.top-context i{width:3px;height:3px;border-radius:50%;background:#697978}.live-dot{height:6px;width:6px;background:#a5dfa9;border-radius:50%;box-shadow:0 0 9px #a5dfa988}.safety-pill{border:1px solid #314238;color:#c3dfc5;padding:8px 11px;border-radius:4px;font-size:9px;letter-spacing:.7px}.safety-pill span{color:#e1f68a;margin-right:5px}.icon-button,.avatar{height:34px;width:34px;border:1px solid #354144;background:transparent;border-radius:50%;color:#aab8b3}.avatar{background:#d7edbd;color:#24322c;border:0;font:700 10px var(--mono)}.workspace{display:grid;grid-template-columns:minmax(0,1.66fr) minmax(340px,.84fr);gap:38px;padding:34px 0 25px}.lab-column{min-width:0}.scene-head{height:73px;display:flex;align-items:flex-start;justify-content:space-between}.eyebrow{font:10px var(--mono);color:#82918d;letter-spacing:1.2px}.tiny-live{font-size:8px;color:#a6e2ae;margin-left:11px}.scene-head h1{font:600 25px var(--display);margin:7px 0 0;letter-spacing:-.7px}.scene-head h1 em,.mission-title-row h2 em{font-weight:500;color:var(--mint);font-style:normal}.scene-tools{display:flex;gap:20px;align-items:center;padding-top:15px;color:#82918d;font:9px var(--mono);letter-spacing:.5px}.mouse-icon{font-size:17px;color:#a3b7aa;vertical-align:-2px;margin-right:5px}.reset-view{background:none;border:0;color:#9eafaa;font:10px var(--mono)}.reset-view span{font-size:9px;margin-left:4px}.scene-frame{position:relative;height:min(49vw,535px);min-height:360px;overflow:hidden;border:1px solid #2d3a3b;background:radial-gradient(ellipse at 48% 67%,#263b3b 0%,#1b2b2e 38%,#142124 77%);border-radius:5px}.scene-frame:before{content:'';position:absolute;inset:0;pointer-events:none;z-index:1;opacity:.16;background-image:linear-gradient(rgba(176,218,191,.13) 1px,transparent 1px),linear-gradient(90deg,rgba(176,218,191,.13) 1px,transparent 1px);background-size:45px 45px;mask-image:linear-gradient(transparent 8%,black 100%)}#labScene{position:absolute;inset:0;z-index:0}#labScene canvas{display:block;width:100%;height:100%;touch-action:none}.scene-vignette{position:absolute;inset:0;pointer-events:none;z-index:1;background:linear-gradient(0deg,rgba(11,17,19,.55),transparent 25%,transparent 80%,rgba(9,15,16,.22))}.scene-label{position:absolute;z-index:2;top:18px;display:flex;align-items:center;gap:8px;color:#8fa29a;font:9px var(--mono);letter-spacing:.8px}.scene-label-left{left:18px}.scene-label-right{right:18px}.scene-label b{color:#d5e5d6;font-weight:400}.label-icon{font-size:14px;color:#b9edc9}.scene-label-left b{color:#a6e3af;font-size:8px}.temp-icon{font-size:17px;color:#f0bb83}.scene-caption{position:absolute;z-index:2;bottom:15px;left:18px;display:flex;align-items:center;gap:9px;color:#9aa8a1;font:9px var(--mono);letter-spacing:.7px}.caption-line{height:1px;width:20px;background:#bddfbe}.scene-toast{position:absolute;z-index:5;left:50%;top:17%;transform:translate(-50%,-6px);opacity:0;transition:.3s;background:#101a19eF;border:1px solid #61776a;border-radius:3px;padding:10px 15px;color:#d9eedc;font:10px var(--mono);letter-spacing:.3px;pointer-events:none}.scene-toast.show{opacity:1;transform:translate(-50%,0)}.reaction-flash{position:absolute;inset:0;z-index:1;opacity:0;pointer-events:none;background:radial-gradient(ellipse at 50% 70%,#c6f4a533,transparent 50%)}.reaction-flash.flash{animation:flash .8s ease-out}@keyframes flash{0%{opacity:0}35%{opacity:1}100%{opacity:0}}.bench-footer{height:43px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #2a3537;color:#788886;font:9px var(--mono);letter-spacing:.35px}.footer-state{display:flex;gap:8px;align-items:center;color:#a3b3ab}.state-orb{height:6px;width:6px;border-radius:50%;background:#a7dfae}.footer-tip b{color:#d3ebaf;font-weight:500;margin-right:5px}.bench-id{color:#74817e}.bench-id span{color:#b4d7ad;margin:0 5px}.reagent-section{padding-top:23px}.section-title-row{display:flex;align-items:end;justify-content:space-between}.section-title-row h2{font:600 17px var(--display);margin:5px 0 0;letter-spacing:-.35px}.count-tag{font:9px var(--mono);color:#9baaa4;background:#263331;padding:4px 5px;border-radius:3px;vertical-align:3px;margin-left:4px}.rack-note{font:9px var(--mono);color:#788986;letter-spacing:.45px}.rack-note span{color:#c4e6b9;font-size:13px;margin-left:6px}.reagent-rack{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:14px}.reagent-card{background:#172023;border:1px solid #2d3a3b;border-radius:4px;min-height:89px;padding:11px 11px 9px;display:grid;grid-template-columns:37px 1fr;gap:10px;align-items:center;text-align:left;transition:.18s;position:relative;overflow:hidden}.reagent-card:hover{background:#202b2c;border-color:#78927c;transform:translateY(-2px)}.reagent-card:active{transform:translateY(0)}.reagent-card.disabled{opacity:.42;pointer-events:none}.reagent-icon{width:34px;height:45px;display:grid;place-items:center;border-bottom:2px solid var(--reagent);position:relative}.reagent-icon:before{content:'';position:absolute;top:0;width:12px;height:8px;background:#65736e;border-radius:2px 2px 0 0}.reagent-icon:after{content:'';position:absolute;bottom:0;width:32px;height:28px;border:1px solid #74867a;border-top:2px solid var(--reagent);border-radius:4px 4px 6px 6px;background:linear-gradient(0deg,var(--reagent-alpha),transparent 70%)}.reagent-icon span{position:relative;z-index:1;color:#e3eee2;font:8px var(--mono);margin-top:11px}.reagent-info{min-width:0}.reagent-info b{font:600 11px var(--display);display:block;white-space:nowrap}.reagent-info small{display:block;color:#86938d;font:9px var(--mono);margin-top:5px;white-space:nowrap}.reagent-info .reagent-formula{font-size:8px;color:#bbd8c0;margin-top:3px}.add-mark{position:absolute;right:8px;top:6px;color:#788983;font:12px var(--mono)}.mission-column{border-left:1px solid #293638;padding-left:28px;position:relative;min-width:0}.mission-header{display:flex;justify-content:space-between;align-items:center}.note-number{border-left:1px solid #41504d;padding-left:8px;margin-left:8px;color:#66736f;font-size:9px}.more-button{background:transparent;border:0;color:#879790;letter-spacing:2px;font-size:15px}.mission-title-row{display:flex;justify-content:space-between;align-items:start;margin-top:15px}.mission-title-row h2{font:600 29px/1.03 var(--display);letter-spacing:-1.3px;margin:0}.mission-title-row p{font-size:11px;color:#94a19d;margin:9px 0 0}.difficulty{border:1px solid #3c4b46;border-radius:3px;padding:7px 9px;text-align:right}.difficulty span{font:8px var(--mono);color:#83928c;display:block}.difficulty b{font:600 17px var(--display);color:#d8eeaf}.mission-select{display:flex;gap:5px;margin-top:20px}.mission-choice{min-width:0;flex:1;background:#172023;border:1px solid #2d3b3c;border-radius:3px;padding:8px 7px;display:flex;gap:7px;text-align:left;align-items:center;transition:.2s}.mission-choice.active{background:#212c2a;border-color:#82967b}.choice-index{font:9px var(--mono);color:#a4d5a5}.mission-choice b{font:600 9px var(--display);display:block;white-space:nowrap}.mission-choice small{font:8px var(--mono);display:block;color:#798783;margin-top:4px;white-space:nowrap}.choice-check{display:none;color:#d5f0ad;font-size:10px;margin-left:auto}.mission-choice.active .choice-check{display:block}.mission-progress{margin-top:20px}.progress-copy{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.55px;color:#83908b}.progress-copy b{font-weight:400;color:#d6e5d7}.progress-track{height:3px;background:#2c3938;border-radius:2px;margin-top:9px}.progress-track i{height:100%;display:block;width:0%;background:#c9e8a4;transition:width .35s;border-radius:2px}.objective-card{margin-top:19px;border:1px solid #36443f;background:linear-gradient(130deg,#1d2827,#182120);border-radius:4px;padding:13px 14px}.objective-top{display:flex;align-items:center;gap:8px;font:9px var(--mono);color:#94a59b;letter-spacing:.5px}.objective-icon{font-size:14px;color:#d0eea2}.objective-status{margin-left:auto;font-size:8px;color:#bdca9d}.objective-card p{color:#bac6bf;font-size:11px;line-height:1.6;margin:11px 0}.objective-card p b{color:#e1edce;font-weight:600}.objective-equation{border-top:1px solid #34413d;padding-top:10px;text-align:center;color:#deead8;font:11px var(--mono);letter-spacing:.2px}.objective-equation span{color:#bce29d;padding:0 6px}.procedure{margin-top:20px}.procedure-heading h3{font:600 15px var(--display);margin:4px 0 0}.step-count{font:8px var(--mono);color:#71827b;padding-bottom:2px}.steps{margin-top:13px}.step{display:grid;grid-template-columns:22px 1fr;gap:9px;position:relative;padding-bottom:12px}.step:not(:last-child):before{content:'';position:absolute;width:1px;background:#35433e;top:20px;bottom:0;left:9px}.step-marker{width:20px;height:20px;border:1px solid #52645a;border-radius:50%;display:grid;place-items:center;color:#8fa496;font:9px var(--mono);background:#151d1f;z-index:1}.step.done .step-marker{background:#c6e8ac;border-color:#c6e8ac;color:#1b2922}.step.active .step-marker{border-color:#d6eeab;color:#d6eeab;box-shadow:0 0 0 3px #d6eeab18}.step-text{font-size:10px;color:#8e9b95;line-height:1.5;padding-top:3px}.step.active .step-text{color:#d3ddd4}.step.done .step-text{color:#a4b7a3}.step-text b{font-weight:600;color:#d0ded2}.step.done .step-text b{color:#bee0b7}.data-panel{border:1px solid #2e3b3c;background:#151e20;border-radius:4px;margin-top:6px;padding:10px 12px}.data-header{display:flex;justify-content:space-between;font:8px var(--mono);letter-spacing:.7px;color:#85928c}.data-live{color:#9dcda3}.data-live i{display:inline-block;width:5px;height:5px;background:#9bdca1;border-radius:50%;margin-right:5px}.readings{display:grid;grid-template-columns:1fr 1fr 1fr;gap:13px;margin-top:12px}.reading{position:relative;min-width:0}.reading>span{display:block;font:8px var(--mono);color:#71817c;letter-spacing:.4px}.reading>b{font:600 17px var(--display);display:block;color:#e0e9df;margin-top:3px;white-space:nowrap}.reading>b small{font:9px var(--mono);font-weight:400;color:#83908a}.ph-meter,.reading-line{height:2px;background:#35413e;margin-top:5px}.ph-meter i,.reading-line i{height:100%;display:block;width:0%;background:#d0eba2;transition:width .3s}.solution-reading{font:10px var(--mono)!important;margin-top:7px!important}.color-dot{position:absolute;right:3px;bottom:0;width:9px;height:9px;background:#d3dcdb;border-radius:50%;border:1px solid #78908d}.notebook-note{display:flex;gap:10px;padding:12px 1px;color:#7f8d86}.note-spark{color:#d1e8a6;font-size:14px}.notebook-note p{font-size:10px;line-height:1.5;margin:0}.reset-button{background:none;border:0;padding:4px 0;color:#74827d;font:9px var(--mono);letter-spacing:.7px}.reset-button:hover{color:#dce7dc}.reset-button span{font-size:14px;color:#a4b8a7;vertical-align:-1px;margin-right:6px}.app-footer{border-top:1px solid #293638;height:45px;display:flex;justify-content:space-between;align-items:center;color:#6e7c77;font:8px var(--mono);letter-spacing:.5px}.app-footer b{color:#a3b0a9;font-weight:400}.app-footer i{color:#d1e8a6;font-style:normal;margin-left:5px}.footer-version{color:#45534e;margin-left:5px}.completion-modal{position:fixed;inset:0;background:#08100fbb;backdrop-filter:blur(8px);z-index:10;display:none;place-items:center;padding:20px}.completion-modal.show{display:grid}.modal-card{position:relative;width:min(410px,100%);background:#182220;border:1px solid #657862;border-radius:5px;padding:35px;text-align:center;box-shadow:0 25px 100px #0008}.modal-close{position:absolute;right:12px;top:10px;background:none;border:0;color:#91a398;font-size:24px}.modal-star{font-size:35px;color:#d6edaa}.modal-card .eyebrow{margin-top:8px}.modal-card h2{font:600 27px var(--display);margin:13px 0 7px}.modal-card p{color:#9baaa0;font-size:12px;line-height:1.6}.result-stamp{border:1px solid #52634f;color:#a2b3a5;padding:10px;margin:20px 0;font:9px var(--mono);letter-spacing:1px}.result-stamp b{color:#d7eca7;margin-left:6px}.modal-button{background:#d0e9ad;border:0;color:#1a2821;width:100%;padding:12px;font:600 10px var(--mono);letter-spacing:.6px}.modal-button span{float:right}
@media(max-width:1100px){.app-shell{padding:0 26px}.workspace{gap:25px;grid-template-columns:minmax(0,1.4fr) minmax(315px,.9fr)}.mission-column{padding-left:20px}.scene-frame{height:48vw;min-height:340px}.reagent-card{padding:9px 7px;grid-template-columns:32px 1fr;gap:6px}.reagent-info b{font-size:10px}.mission-title-row h2{font-size:26px}}
@media(max-width:800px){.app-shell{padding:0 18px}.workspace{grid-template-columns:1fr;gap:24px;padding-top:25px}.scene-frame{height:min(67vw,510px);min-height:320px}.mission-column{border-left:0;border-top:1px solid #293638;padding:23px 0 0}.mission-title-row h2 br{display:none}.mission-title-row h2{font-size:30px}.mission-column{display:grid;grid-template-columns:1fr 1fr;column-gap:20px}.mission-header,.mission-title-row,.mission-select,.mission-progress,.objective-card,.procedure,.data-panel,.notebook-note,.reset-button{grid-column:span 2}.mission-title-row{margin-top:10px}.mission-select{margin-top:14px}.objective-card{margin-top:15px}.procedure{margin-top:17px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.step{padding:0}.step:not(:last-child):before{display:none}.data-panel{margin-top:16px}.notebook-note{padding-bottom:7px}.reset-button{padding-bottom:10px}.top-context{display:none}.topbar{height:65px}.app-footer{font-size:7px}}
@media(max-width:520px){.app-shell{padding:0 13px}.topbar{height:60px}.top-actions{gap:7px}.safety-pill{padding:7px;font-size:8px}.icon-button,.avatar{width:30px;height:30px}.workspace{padding-top:20px;gap:18px}.scene-head{height:67px}.scene-head h1{font-size:22px}.scene-tools{gap:9px;font-size:0}.reset-view span{display:none}.scene-frame{height:75vw;min-height:290px;max-height:420px}.scene-hint{display:none}.bench-footer{height:38px}.footer-tip{display:none}.bench-id{font-size:8px}.reagent-section{padding-top:19px}.reagent-rack{grid-template-columns:1fr 1fr;gap:7px;margin-top:11px}.reagent-card{min-height:77px;grid-template-columns:35px 1fr;padding:8px}.reagent-info b{font-size:11px}.reagent-info small{font-size:8px}.rack-note{font-size:7px}.mission-column{grid-template-columns:1fr;column-gap:0}.mission-header,.mission-title-row,.mission-select,.mission-progress,.objective-card,.procedure,.data-panel,.notebook-note,.reset-button{grid-column:1}.mission-title-row h2{font-size:27px}.mission-select{gap:4px}.mission-choice{padding:7px 5px;gap:5px}.choice-index{font-size:8px}.mission-choice b{font-size:8px}.mission-choice small{font-size:7px}.steps{display:block}.step{padding-bottom:11px}.step:not(:last-child):before{display:block}.step-text{font-size:10px}.app-footer{height:auto;min-height:48px;gap:8px;flex-wrap:wrap;padding:9px 0}.app-footer span:last-child{width:100%;text-align:left}.scene-label{top:12px;font-size:8px}.scene-label-left{left:11px}.scene-label-right{right:11px}.scene-caption{left:11px;bottom:11px;font-size:8px}.section-title-row h2{font-size:16px}}

import * as THREE from 'three';

const experiments={
 neutral:{title:'A matter of<br><em>neutrality</em>',subtitle:'Can you bring this solution to a neutral pH?',level:'01',objective:'Neutralize <b>25 mL</b> of 0.10 M hydrochloric acid using an equal amount of sodium hydroxide.',equation:'HCl <span>+</span> NaOH <span>→</span> NaCl + H₂O',steps:[['Add the acid','Dispense 25 mL of 0.10 M hydrochloric acid into the clean beaker.'],['Neutralize it','Add 25 mL of 0.10 M sodium hydroxide. The temperature may rise slightly.'],['Check the endpoint','Add a few drops of phenolphthalein. A neutral solution remains colorless.']],items:['hcl','naoh','phen'],initialPH:null},
 displace:{title:'A metal<br><em>exchange</em>',subtitle:'Can one metal push another out of solution?',level:'02',objective:'Place a clean iron nail in <b>20 mL</b> of copper(II) sulfate and watch for a single-displacement reaction.',equation:'Fe <span>+</span> CuSO₄ <span>→</span> FeSO₄ + Cu',steps:[['Prepare the solution','Add 20 mL of 0.10 M copper(II) sulfate to the beaker.'],['Introduce iron','Dip the clean iron nail into the blue solution.'],['Observe the change','Watch copper form on the nail as the blue color fades.']],items:['cuso4','iron','observe'],initialPH:null},
 gas:{title:'The invisible<br><em>product</em>',subtitle:'Can you make a gas — then prove it is there?',level:'03',objective:'React <b>20 mL</b> of vinegar with sodium bicarbonate, then test the gas with limewater.',equation:'CH₃COOH <span>+</span> NaHCO₃ <span>→</span> CH₃COONa + H₂O + CO₂',steps:[['Measure the acid','Add 20 mL of 5% acetic acid (vinegar) to the flask.'],['Add bicarbonate','Add 2 g of sodium bicarbonate. Bubbles of carbon dioxide form.'],['Test the gas','Pass the gas through limewater. It turns cloudy as calcium carbonate forms.']],items:['vinegar','bicarb','lime'],initialPH:null}
};
const reagents={
 hcl:{name:'Hydrochloric acid',formula:'HCl · 0.10 M',qty:'25 mL',color:'#b6c4c6',hex:0xb6d5d3},naoh:{name:'Sodium hydroxide',formula:'NaOH · 0.10 M',qty:'25 mL',color:'#d9e3cb',hex:0xcbdcc4},phen:{name:'Phenolphthalein',formula:'Indicator · 2 drops',qty:'2 drops',color:'#ef91b2',hex:0xe98bb2},cuso4:{name:'Copper sulfate',formula:'CuSO₄ · 0.10 M',qty:'20 mL',color:'#39a6c5',hex:0x1599c5},iron:{name:'Iron nail',formula:'Fe · 1 clean nail',qty:'1 nail',color:'#b88258',hex:0x9c745b},observe:{name:'Observe reaction',formula:'Visual inspection',qty:'observe',color:'#d5e0bb',hex:0xc5d5a4},vinegar:{name:'Vinegar',formula:'CH₃COOH · 5%',qty:'20 mL',color:'#d8c6a1',hex:0xc7ae78},bicarb:{name:'Sodium bicarbonate',formula:'NaHCO₃ · solid',qty:'2 g',color:'#e4e6d9',hex:0xdfdfcf},lime:{name:'Limewater',formula:'Ca(OH)₂ · dilute',qty:'10 mL',color:'#d9edb1',hex:0xb7d26e}
};
let mission='neutral', step=0, volume=0, temp=22, ph=null, reactionDone=false, currentColor=0xd8e1de, soundOn=false;
const $=s=>document.querySelector(s), sceneRoot=$('#labScene');
