function renderMission(){const m=experiments[mission];$('#missionTitle').innerHTML=m.title;$('#missionSubtitle').textContent=m.subtitle;$('#missionLevel').textContent=m.level;$('#objectiveText').innerHTML=m.objective;$('#equation').innerHTML=m.equation;$('#steps').innerHTML=m.steps.map((s,i)=>`<div class="step ${i<step?'done':i===step?'active':''}"><span class="step-marker">${i<step?'✓':String(i+1).padStart(2,'0')}</span><span class="step-text"><b>${s[0]}</b><br>${s[1]}</span></div>`).join('');$('#stepCount').textContent=`STEP ${String(Math.min(step+1,m.steps.length)).padStart(2,'0')} / ${String(m.steps.length).padStart(2,'0')}`;$('#progressText').textContent=`${step} / ${m.steps.length}`;$('#progressBar').style.width=`${Math.round(step/m.steps.length*100)}%`;$('#objectiveStatus').textContent=step===m.steps.length?'COMPLETE':'IN PROGRESS';$('#reagentRack').innerHTML=m.items.map((id,i)=>{const r=reagents[id];return `<button class="reagent-card" data-reagent="${id}" style="--reagent:${r.color};--reagent-alpha:${r.color}55" aria-label="Add ${r.name}"><span class="add-mark">+</span><span class="reagent-icon"><span>${id==='iron'?'Fe':id==='observe'?'◎':id==='phen'?'IND':id==='vinegar'?'Ac':id==='bicarb'?'Na':id==='lime'?'Ca':id==='cuso4'?'Cu':id==='naoh'?'Na':'HCl'}</span></span><span class="reagent-info"><b>${r.name}</b><small>${r.qty}</small><small class="reagent-formula">${r.formula}</small></span></button>`}).join('');$('#reagentCount').textContent=String(m.items.length).padStart(2,'0');$('#reagentRack').querySelectorAll('[data-reagent]').forEach(b=>b.onclick=()=>addReagent(b.dataset.reagent));updateReadouts()}
